def codigo_de(texto):
    sin_acentos = unicodedata.normalize('NFKD', texto or '').encode('ascii', 'ignore').decode()
    return sin_acentos.strip().upper().replace(' ', '_')


def migrar_equipos(apps, schema_editor):
    """
    - El texto `tipo_equipo_requerido` de cada operación pasa a un EquipoOperacion (1 equipo de ese tipo).
    - Las fases de lotes vigentes reciben su requerimiento de equipo copiado de la receta.
    - Los equipos asignados a mano (`equipos_asignados`) pasan a ser reservas.
    """
    TipoEquipo = apps.get_model('actividades', 'TipoEquipo')
    OperacionProceso = apps.get_model('procesos', 'OperacionProceso')
    EquipoOperacion = apps.get_model('procesos', 'EquipoOperacion')
    FaseLote = apps.get_model('procesos', 'FaseLote')
    EquipoFase = apps.get_model('procesos', 'EquipoFase')
    ReservaEquipo = apps.get_model('procesos', 'ReservaEquipo')

    for op in OperacionProceso.objects.exclude(tipo_equipo_requerido__in=['', 'N/A']):
        codigo = codigo_de(op.tipo_equipo_requerido)
        tipo, _ = TipoEquipo.objects.get_or_create(codigo=codigo, defaults={'nombre': op.tipo_equipo_requerido.strip()})
        EquipoOperacion.objects.get_or_create(operacion=op, tipo=tipo, aplica_a='ACTIVIDAD')

    fases = FaseLote.objects.filter(lote__archivado=False, es_subtarea_muestreo=False).exclude(lote__estado='ABORTADO')
    for fase in fases:
        for eo in EquipoOperacion.objects.filter(operacion_id=fase.operacion_maestra_id, aplica_a='ACTIVIDAD'):
            EquipoFase.objects.get_or_create(fase=fase, tipo_id=eo.tipo_id, defaults={
                'cantidad': eo.cantidad, 'cantidad_receta': eo.cantidad,
                'horas_preparacion': eo.horas_preparacion, 'horas_limpieza': eo.horas_limpieza,
            })

    for fase in FaseLote.objects.filter(equipos_asignados__isnull=False).distinct():
        for equipo in fase.equipos_asignados.all():
            requerimiento, _ = EquipoFase.objects.get_or_create(fase=fase, tipo_id=equipo.tipo_id, defaults={'cantidad': 0})
            ReservaEquipo.objects.create(equipo_fase=requerimiento, equipo=equipo)
            if requerimiento.reservas.filter(activo=True).count() > requerimiento.cantidad:
                requerimiento.cantidad = requerimiento.reservas.filter(activo=True).count()
                requerimiento.save()


